using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using MapSharedProps.EditorTools;
public static class Lamp100Checks {
 static string Root=>Path.GetFullPath(Path.Combine(Application.dataPath,".."));static void Check(bool v,string s){if(!v)throw new Exception(s);}
 static Dictionary<string,GameObject> Build(string stage){string folder="Assets/Imported100-"+stage;if(stage=="before"&&AssetDatabase.IsValidFolder(folder)){var cached=new Dictionary<string,GameObject>();foreach(var file in Directory.GetFiles(Path.Combine(Root,folder),"small-*.prefab")){var asset=AssetDatabase.LoadAssetAtPath<GameObject>(folder+"/"+Path.GetFileName(file));cached.Add(Path.GetFileNameWithoutExtension(file).Substring(6),asset);}Check(cached.Count==43,"43 baseline Prefabs retained");return cached;}Check(!AssetDatabase.IsValidFolder(folder),"Fresh test output required");AssetDatabase.CreateFolder("Assets",folder.Substring(7));var root=new GameObject("Lantern "+stage);var p=new Dictionary<string,GameObject>();Check(SmallPropsV1.Build(Path.Combine(Root,"Input100-"+stage),folder,root.transform,Shader.Find("MapSharedProps/Lit"),p)==1&&p.Count==43,"43 prefabs/one lantern");PrefabUtility.SaveAsPrefabAsset(root,"Assets/lamp100-"+stage+".prefab");UnityEngine.Object.DestroyImmediate(root);AssetDatabase.SaveAssets();return p;}
 static string LightKey(Light l)=>$"{l.type}/{l.color}/{l.intensity:R}/{l.range:R}/{l.shadows}/{l.transform.localPosition}";
 static string[] FireState(GameObject root)=>root.GetComponentsInChildren<ParticleSystem>(true).Select(p=>$"{p.name}/{p.main.maxParticles}/{p.main.startLifetime.constantMin:R}/{p.main.startLifetime.constantMax:R}/{p.emission.rateOverTime.constant:R}/{p.shape.radius:R}").Concat(root.GetComponentsInChildren<Light>(true).Select(LightKey)).OrderBy(x=>x).ToArray();
 public static void Run(){int exit=0;string output=Path.Combine(Root,"Evidence100Import");Directory.CreateDirectory(output);try{
 EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var before=Build("before");var after=Build("after2");
 var ca=before["lantern"].GetComponent<MeshCollider>().sharedMesh;var cb=after["lantern"].GetComponent<MeshCollider>().sharedMesh;Check(ca.vertices.SequenceEqual(cb.vertices)&&ca.triangles.SequenceEqual(cb.triangles),"lantern collider exact");
 foreach(var id in before.Keys.Where(x=>x!="lantern"))Check(before[id].GetComponent<MeshFilter>().sharedMesh==after[id].GetComponent<MeshFilter>().sharedMesh,"unrelated mesh exact "+id);
 Check(LightKey(before["lantern"].GetComponentInChildren<Light>())==LightKey(after["lantern"].GetComponentInChildren<Light>()),"lantern light exact");Check(after["lantern"].GetComponentsInChildren<Light>().Length==1,"one lantern light");
 var m=after["lantern"].GetComponent<MeshFilter>().sharedMesh;Check(m.vertexCount/3<1100,"lantern triangle budget");Check(m.vertices.All(v=>float.IsFinite(v.x)&&float.IsFinite(v.y)&&float.IsFinite(v.z)),"finite geometry");
 var ma=before["lantern"].GetComponent<Renderer>().sharedMaterial;var mb=after["lantern"].GetComponent<Renderer>().sharedMaterial;Check(ma.shader==mb.shader&&ma.shaderKeywords.SequenceEqual(mb.shaderKeywords)&&ma.GetTexture("_BaseMap")==mb.GetTexture("_BaseMap"),"same shader keywords and texture");
 var fireRoots=new List<GameObject>();foreach(string stage in new[]{"before","after2"}){var root=new GameObject("Fire unchanged "+stage);var fireFolder="Assets/Imported100-"+stage+"/FireFinal";if(!AssetDatabase.IsValidFolder(fireFolder))AssetDatabase.CreateFolder("Assets/Imported100-"+stage,"FireFinal");Check(FirePropsBuilder.Build(Path.Combine(Root,"Input100-"+stage),fireFolder,root.transform,Shader.Find("MapSharedProps/Lit"))==2,"torch/brazier import");fireRoots.Add(root);}Check(FireState(fireRoots[0]).SequenceEqual(FireState(fireRoots[1])),"fire particle/light configuration exact");foreach(var root in fireRoots)UnityEngine.Object.DestroyImmediate(root);
 File.WriteAllText(Path.Combine(output,"checks.json"),"{\"pass\":true,\"cases\":[\"before\",\"after2\"],\"prefabsPerCase\":43,\"lanternPlacementsPerCase\":1,\"firePlacementsPerCase\":2,\"colliderExact\":true,\"unrelated42MeshesExact\":true,\"lanternLightExact\":true,\"fireParticlesAndLightsExact\":true,\"sameShaderAndTexture\":true,\"readerSourceUnchanged\":true,\"playerExecuted\":false}");
 }catch(Exception e){Debug.LogException(e);File.WriteAllText(Path.Combine(output,"error.txt"),e.ToString());exit=1;}finally{EditorApplication.Exit(exit);}}
}
